SRC=$1; OUT=$2; T=/run/media/doletrandat/AOSP-BUILD/aosp11; A=$T/.codex-restart/artifacts/pf31-phone-audio-power-20261031
CC=$T/prebuilts/clang/host/linux-x86/clang-r383902b1/bin/clang
cd $T; mkdir -p $OUT
$CC -std=gnu11 -D_GNU_SOURCE -Wall -Wextra -Werror -fPIC --target=armv7a-linux-androideabi10000 -march=armv7-a -mfpu=neon -mfloat-abi=softfp -nostdlibinc -I$T/hardware/libhardware/include -I$T/system/core/libcutils/include -I$T/system/core/libsystem/include -I$T/system/core/libutils/include -I$T/system/libbase/include -I$T/bionic/libc/include -I$T/bionic/libc/kernel/uapi -I$T/bionic/libc/kernel/uapi/asm-arm -I$T/bionic/libc/kernel/android/uapi -Iexternal/tinyalsa/include -Isystem/logging/liblog/include -Isystem/core/liblog/include -Wno-unused-parameter -Isystem/media/audio/include -Isystem/media/audio_utils/include -c $SRC -o $OUT/audio_hw.o
$CC $OUT/audio_hw.o $A/hal-link-providers/libcutils.so $A/pcm-test-build-02/pcm.o $A/hal-link-providers/liblog.so out/soong/.intermediates/bionic/libc/crtbegin_so/android_arm_armv7-a-neon_cortex-a7/crtbegin_so.o -Wl,--start-group prebuilts/clang/host/linux-x86/clang-r383902b1/lib64/clang/11.0.2/lib/linux/libclang_rt.builtins-arm-android.a prebuilts/gcc/linux-x86/arm/arm-linux-androideabi-4.9/arm-linux-androideabi/lib/libatomic.a -Wl,--end-group out/soong/.intermediates/bionic/libc/libc/android_arm_armv7-a-neon_cortex-a7_shared_10000/libc.so out/soong/.intermediates/bionic/libm/libm/android_arm_armv7-a-neon_cortex-a7_shared_10000/libm.so out/soong/.intermediates/bionic/libdl/libdl/android_arm_armv7-a-neon_cortex-a7_shared_10000/libdl.so out/soong/.intermediates/bionic/libc/crtend_android/android_arm_armv7-a-neon_cortex-a7/obj/bionic/libc/arch-common/bionic/crtend.o -o $OUT/audio.primary.superman.so -target armv7a-linux-androideabi10000 -Bprebuilts/gcc/linux-x86/arm/arm-linux-androideabi-4.9/arm-linux-androideabi/bin -Wl,-z,noexecstack -Wl,-z,relro -Wl,-z,now -Wl,--build-id=md5 -Wl,--warn-shared-textrel -Wl,--fatal-warnings -Wl,--no-undefined-version -Wl,--exclude-libs,libgcc.a -Wl,--exclude-libs,libgcc_stripped.a -Wl,--exclude-libs,libunwind_llvm.a -fuse-ld=lld -Wl,--pack-dyn-relocs=android+relr -Wl,--use-android-relr-tags -Wl,--no-undefined -Wl,--icf=safe -Wl,--hash-style=gnu -Wl,-m,armelf -Wl,--exclude-libs=libclang_rt.builtins-arm-android.a -nostdlib -Bdynamic -Wl,--gc-sections -Wl,-z,nocopyreloc -Wl,--exclude-libs,libunwind_llvm.a -shared
